% Generated by GitHub Copilot under Lance Lascari's direction.
% Worked datasheet extraction: Mini-Circuits ROS-2100-119+, REV. E, page 2.
% GNU Octave first; MATLAB compatible. No PDF/parser is needed to run this.
% See ros2100_extraction_example.md for evidence, limitations and LLM prompt.
%
% Run this script by name after adding pn/ to the path. It leaves pn_struct
% (the representative legacy curve) and pn_profile_s (all points) in memory.
% Results go to datfiles_local/ beside this script, not the current directory.
% The MAT file contains both variables; older tools still load pn_struct.
% Rerunning replaces this script's previous plots, leaving other figures alone.

tool_directory=fileparts(mfilename('fullpath'));
addpath(tool_directory);

% Select a legacy export. 1725 MHz has a detailed, directly tabulated curve.
% Other frequencies must be exact stored points unless interpolation is enabled.
representative_fc_Hz=1725e6;
selection_mode='exact'; % 'interpolate' explicitly permits a modeled curve
output_filename=fullfile(tool_directory,'datfiles_local','ROS_2100_119_profile.mat');
bSaveData=1; % set to 0 to construct in memory without creating a file
bOverwriteData=1; % explicitly enable only when replacing this example output
bPlotData=1; % phase-noise overlay and tuning sensitivity versus carrier frequency

% A calling demo can override these four run/output settings without editing
% the extraction rows or this script's interactive defaults.
if exist('ros_example_options_s','var')
    if ~isstruct(ros_example_options_s) || ~isscalar(ros_example_options_s)
        error('ros_example_options_s must be a scalar structure.');
    end
    option_names=fieldnames(ros_example_options_s);
    if ~all(ismember(option_names,{'bSaveData','bOverwriteData','bPlotData','output_filename'}))
        error('Unsupported ROS example option; use bSaveData, bOverwriteData, bPlotData or output_filename.');
    end
    if isfield(ros_example_options_s,'bSaveData')
        bSaveData=ros_example_options_s.bSaveData;
    end
    if isfield(ros_example_options_s,'bOverwriteData')
        bOverwriteData=ros_example_options_s.bOverwriteData;
    end
    if isfield(ros_example_options_s,'bPlotData')
        bPlotData=ros_example_options_s.bPlotData;
    end
    if isfield(ros_example_options_s,'output_filename')
        output_filename=ros_example_options_s.output_filename;
    end
    validateattributes(bSaveData,{'numeric','logical'},{'scalar','binary'});
    validateattributes(bOverwriteData,{'numeric','logical'},{'scalar','binary'});
    validateattributes(bPlotData,{'numeric','logical'},{'scalar','binary'});
    if ~ischar(output_filename) || isempty(output_filename) || ~isrow(output_filename)
        error('ROS output_filename must be a nonempty character row.');
    end
end

% Page 2 left table: use the +25 C frequency column; do not sweep temperature.
% Columns: tuning voltage (V), carrier (MHz), tuning sensitivity (MHz/V),
% and typical SSB phase noise (dBc/Hz) at 1, 10, 100 and 1000 kHz offsets.
% The characterization extends beyond the page 1 specified 1350-2100 MHz band.
band_data=[
     0.00 1041.5 110.21 -73.8 -101.0 -121.2 -140.9
     0.50 1094.3  93.57 -74.3 -101.9 -122.2 -141.8
     1.00 1139.5  85.25 -76.5 -101.8 -122.4 -141.9
     1.50 1180.5  81.79 -76.8 -101.2 -122.3 -141.8
     2.50 1257.6  77.06 -76.9 -101.9 -122.2 -140.0
     3.50 1331.0  73.60 -79.2 -101.4 -122.3 -141.9
     4.50 1403.0  71.30 -76.9 -101.3 -122.5 -142.1
     5.50 1472.7  68.10 -79.0 -102.2 -122.7 -142.1
     6.50 1539.5  65.02 -75.8 -101.9 -122.7 -142.3
     7.50 1604.2  64.00 -76.6 -102.4 -123.1 -142.6
     8.50 1666.4  62.59 -75.0 -102.1 -123.0 -142.8
     9.50 1727.0  62.85 -76.5 -101.8 -123.1 -143.2
    10.50 1786.5  61.06 -76.2 -101.7 -123.0 -143.1
    11.50 1843.8  58.11 -75.1 -101.2 -122.9 -142.8
    12.50 1899.8  56.70 -74.9 -101.0 -122.9 -143.2
    13.50 1953.2  54.02 -76.3 -100.7 -122.4 -142.6
    14.50 2006.2  51.46 -76.4 -100.7 -122.1 -142.6
    15.50 2055.7  47.49 -74.4 -100.6 -121.8 -142.2
    16.50 2102.9  45.18 -75.5 -100.5 -121.7 -142.0
    18.50 2187.1  35.58 -74.1 -100.2 -121.7 -141.8
];
band_offsets_Hz=[1e3 10e3 100e3 1e6];
clear ar_pn_struct;
for ii=1:size(band_data,1)
    comment=sprintf(['ROS-2100-119+ REV. E, PDF/printed page 2, left performance table ' ...
        'row %d; Vtune=%.2f V; nominal +25 C, Vcc=8 V, 50 ohm system. ' ...
        'Carrier, Kvco and SSB phase noise directly tabulated; not a guaranteed band specification.'], ...
        ii,band_data(ii,1));
    ar_pn_struct(ii)=build_pn_struct(band_data(ii,2)*1e6,band_data(ii,3)*1e6, ...
        band_offsets_Hz,band_data(ii,4:7),comment, ...
        sprintf('ROS_2100_119_%.1f_MHz',band_data(ii,2)));
end

% Page 2 right table: detailed trace at 1725 MHz (offset kHz, SSB dBc/Hz).
% These are printed numbers, not graph-read estimates. The graph is a check.
detailed_data=[
       1.0  -76.17
       2.0  -83.67
       3.5  -89.73
       6.0  -94.46
       8.5  -98.27
      10.0 -101.89
      20.8 -105.98
      35.5 -110.76
      60.7 -114.58
      86.7 -118.63
     100.0 -123.32
     148.1 -123.14
     177.0 -124.85
     211.6 -126.40
     302.4 -129.33
     361.5 -130.42
     507.5 -134.00
     606.7 -135.51
     851.6 -141.41
    1000.0 -143.24
];

% The detailed table gives no Kvco or Vtune at exactly 1725 MHz.
% Estimate Kvco between the 1666.4 and 1727.0 MHz rows (not a measurement).
detail_fc_Hz=1725e6;
detail_kvco_Hz_V=interp1(band_data(:,2)*1e6,band_data(:,3)*1e6,detail_fc_Hz,'linear');
detail_comment=['ROS-2100-119+ REV. E, PDF/printed page 2, right 1725 MHz table; ' ...
    'SSB phase noise directly tabulated, nominal +25 C, Vcc=8 V, 50 ohm system. ' ...
    'Kvco DERIVED by linear interpolation of left-table rows 11 and 12 ' ...
    '(1666.4 MHz/62.59 MHz/V and 1727.0 MHz/62.85 MHz/V); Vtune not specified.'];
detail_point=build_pn_struct(detail_fc_Hz,detail_kvco_Hz_V, ...
    detailed_data(:,1).'*1e3,detailed_data(:,2).',detail_comment,'ROS_2100_119_1725_MHz');
ar_pn_struct(end+1)=detail_point;
[~,order]=sort([ar_pn_struct.fc]);
ar_pn_struct=ar_pn_struct(order);

% Version 1 wrapper preserves complete single-curve fields at every point.
pn_profile_s.schema_version=1;
pn_profile_s.points=ar_pn_struct;
pn_profile_s.representative_index=find([ar_pn_struct.fc]==detail_fc_Hz,1);
pn_profile_s.source=['Mini-Circuits ROS-2100-119+.pdf, REV. E, M176828, ' ...
    'EDR-7662/1, 191223, pages 1-2; source SHA-256 ' ...
    'b5d00f4dbaed62af625a47ddcc5056ba26dc950b333853a04b0c5fbb349808e8'];
validate_pn_profile(pn_profile_s);
[pn_struct,selection_s]=select_pn_profile(pn_profile_s,representative_fc_Hz,selection_mode);
% representative_index denotes a stored default, not an interpolated result.
if strcmp(selection_s.mode,'exact')
    pn_profile_s.representative_index=selection_s.indices;
end

if bSaveData
    output_directory=fileparts(output_filename);
    if exist(output_directory,'dir')~=7
        [ok,message]=mkdir(output_directory);
        if ~ok
            error('Cannot create example output directory: %s',message);
        end
    end
    if exist(output_filename,'file')==2 && ~bOverwriteData
        error('Example output already exists; enable bOverwriteData or choose another filename.');
    end
    % MATLAB v7 format is readable by both runtimes; no runtime-specific default.
    save(output_filename,'pn_struct','pn_profile_s','selection_s','-v7');
    fprintf('Saved legacy pn_struct and version 1 pn_profile_s to %s\n',output_filename);
end
if bPlotData
    if exist('ros_plot_figure','var') && isgraphics(ros_plot_figure,'figure') && ...
            strcmp(get(ros_plot_figure,'Tag'),'ROS2100Example')
        close(ros_plot_figure);
    end
    plot_points=pn_profile_s.points;
    for ii=1:numel(plot_points)
        plot_points(ii).name=sprintf('%.1f MHz',plot_points(ii).fc/1e6);
    end
    ros_plot_figure=plot_pn_array(plot_points);
    set(ros_plot_figure,'Tag','ROS2100Example');
    legend('NumColumns',2);

    if exist('ros_kvco_figure','var') && isgraphics(ros_kvco_figure,'figure') && ...
            strcmp(get(ros_kvco_figure,'Tag'),'ROS2100KvcoExample')
        close(ros_kvco_figure);
    end
    ros_kvco_figure=figure('Tag','ROS2100KvcoExample');
    plot(band_data(:,2),band_data(:,3),'-o','DisplayName','Tabulated Kvco');
    hold on;
    plot(detail_point.fc/1e6,detail_point.kvco/1e6,'s', ...
        'DisplayName','Derived Kvco at 1725 MHz');
    hold off;
    xlabel('Carrier frequency (MHz)');
    ylabel('Tuning sensitivity (MHz/V)');
    title('ROS-2100-119+ tuning sensitivity');
    grid on;
    axis tight;
    leg1=legend('show');
    set(leg1,'Interpreter','none');
end
